import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Explanation","description":"","frontmatter":{},"headers":[],"relativePath":"research-dts/explanation/index.md","filePath":"vendored/research-dts/explanation/index.md"}`),a={name:`research-dts/explanation/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to “Explanation”">​</a></h1><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to “The problem”">​</a></h2><p>In an effect system with explicit nesting, the programmer writes</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>handle (handle (handle body H1) H2) H3</span></span></code></pre></div><p>and the trouble is that they already <em>know</em> the intent (&quot;Auth must be inside Cache&quot;) but must still translate it into an order, by hand, every time. Ordering mistakes are silent: the program still runs, with different effect semantics.</p><h2 id="why-a-static-ordering-is-enough" tabindex="-1">Why a static ordering is enough <a class="header-anchor" href="#why-a-static-ordering-is-enough" aria-label="Permalink to “Why a static ordering is enough”">​</a></h2><p>An arrow imposes a <strong>linear, sequential</strong> structure on the operations of a handler: there is no concurrent interleaving to account for. So the topology does not need to be discovered at runtime — it can be decided once, at compile time, as a linear extension of the declared precedence relation. That is the whole proposal: the compiler computes the extension and folds it into the nested <code>handle</code> term.</p><h2 id="what-has-to-be-true-for-that-to-be-sound" tabindex="-1">What has to be true for that to be sound <a class="header-anchor" href="#what-has-to-be-true-for-that-to-be-sound" aria-label="Permalink to “What has to be true for that to be sound”">​</a></h2><p>The formalization is the argument that the shortcut is legitimate:</p><ul><li><strong>Precedence is a partial order.</strong> A cycle in the declared relation has no linear extension, so it must be rejected rather than silently reordered — <code>cyclic_detection</code> is that case.</li><li><strong>Any linear extension is a valid topology.</strong> The topological-sort development (<code>ListDigraph/TopSort</code>, <code>Dts/TopoSort</code>) establishes that the extension respects every declared relation.</li><li><strong>Nesting order determines semantics.</strong> <code>Dts/Semantics</code> gives the meaning of a nested <code>handle</code>; <code>Dts/SemanticEquivalence</code> connects the synthesized term to it, so synthesis is not merely a rearrangement of syntax.</li><li><strong>Unrelated handlers commute — sometimes.</strong> <code>Dts/Commutativity</code> states when two handlers may be reordered, which is exactly the freedom the tie-break rule uses.</li></ul><h2 id="determinism-is-part-of-the-contract" tabindex="-1">Determinism is part of the contract <a class="header-anchor" href="#determinism-is-part-of-the-contract" aria-label="Permalink to “Determinism is part of the contract”">​</a></h2><p>Unrelated handlers have no precedence constraint, so <em>some</em> order must be chosen. The implementation uses declaration order as the tie-break, which makes the synthesized term a function of the input text — two runs of the compiler on the same source always emit the same nesting. Without that, the pass would be correct but unreproducible.</p><h2 id="why-there-is-a-python-implementation-at-all" tabindex="-1">Why there is a Python implementation at all <a class="header-anchor" href="#why-there-is-a-python-implementation-at-all" aria-label="Permalink to “Why there is a Python implementation at all”">​</a></h2><p>A proof says the transformation is sound; it does not say the transformation is implementable or pleasant. The reference pipeline (<code>dts.precedence_parser</code> plus the case studies) keeps the formalization honest against concrete precedence shapes — middleware stacks, event-driven orders, cyclic specs — and the property suite turns the paper&#39;s claims into runnable checks.</p><p>See the <a href="/docs/research-dts/reference/">reference</a> for the modules and the <a href="/docs/research-dts/how-to/">how-to guides</a> for build recipes.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};